{
    Task<string?> ChooseFileToOpenAsync(IReadOnlyList<string> extensions);
    Task<string?> ChooseFileToSaveAsync(string suggestedName, IReadOnlyList<string> extensions);
}

/// <summary>
/// What the router needs from a host. <see cref="MosaicRuntimeHost"/> is a
/// static class, so it cannot implement an interface itself;
/// <see cref="MosaicRuntimeHostEffects"/> forwards to it, and a test supplies
/// a fake, so routing and deferral run without a Rust runtime.
/// </summary>
