public static class MosaicPlatformEffects
{
    /// <summary>The effect kinds this library answers unless an app claims them.</summary>
    public static readonly IReadOnlySet<string> StandardEffectKinds =
        new HashSet<string>(StringComparer.Ordinal) { "files.open", "files.save" };

    /// <summary>The largest file <c>files.open</c> reads (UI59 parity with every other host).</summary>
    public const long MaxOpenBytes = 50L * 1024 * 1024;

    /// <summary>The largest payload <c>files.save</c> writes (UI87 §3.1).</summary>
    public const int MaxSaveBytes = 16 * 1024 * 1024;

    // The MIME types an app names, and the extensions a picker filters on --
    // the same table, in the same order, as the Compose library (a Rust test
    // pins the two together). A type this table does not know is dropped
    // rather than failing the request (UI59 §3).
    private static readonly (string Mime, string[] Extensions)[] MimeExtensions =
    {
        ("application/json", new[] { "json" }),
        ("text/plain", new[] { "txt" }),
        ("text/markdown", new[] { "md", "markdown" }),
        ("text/csv", new[] { "csv" }),
        ("application/pdf", new[] { "pdf" }),
        ("application/zip", new[] { "zip" }),
        ("image/jpeg", new[] { "jpg", "jpeg" }),
        ("image/png", new[] { "png" }),
        ("image/webp", new[] { "webp" }),
        ("image/gif", new[] { "gif" }),
        ("image/bmp", new[] { "bmp" }),
        ("image/tiff", new[] { "tif", "tiff" }),
        ("image/svg+xml", new[] { "svg" }),
    };

    /// <summary>
    /// Extensions that run when the file is opened, on some platform: when an
    /// app names no type (<c>accept</c> empty) a save may not end in one of
    /// these, so a <c>files.save</c> cannot drop a launcher next to the
    /// person's documents. When the app does name types, the name must
    /// already end in one of theirs. One list on every host (a Rust test pins
    /// it to the Compose library's).
    /// </summary>
    public static readonly IReadOnlySet<string> ExecutableExtensions = new HashSet<string>(StringComparer.Ordinal)
    {
        // macOS: Terminal scripts, Finder location files and installers open
        // with no prompt, or install.
        "command", "terminal", "tool", "webloc", "inetloc", "fileloc", "afploc", "ftploc",
        "mailloc", "newsloc", "atloc", "app", "pkg", "mpkg", "dmg", "mobileconfig", "scpt",
        "applescript", "workflow",
        // Windows: run, install, or leak credentials when merely browsed.
        "exe", "com", "bat", "cmd", "scr", "pif", "msi", "msp", "msc", "lnk", "url", "hta",
        "cpl", "chm", "inf", "vbs", "vbe", "js", "jse", "wsf", "wsh", "ws", "wsc", "sct",
        "ps1", "psm1", "reg", "jar", "jnlp", "gadget", "xll", "appref-ms", "application",
        "settingcontent-ms", "appx", "msix", "appinstaller", "diagcab", "scf",
        "library-ms", "searchconnector-ms", "iso", "img", "vhd", "vhdx",
        // Linux desktops.
        "desktop", "sh", "run", "appimage", "deb", "rpm", "flatpakref",
    };

    // ── Outcomes ────────────────────────────────────────────────────────
    //
    // Dictionaries of `object?`, because the host serialises the answer with
    // System.Text.Json, which writes an `object`-typed value by its runtime
    // type: `{"ok": {...}}`, `{"cancelled": {}}`, `{"failed": {"message": ...}}`.

    private static Dictionary<string, object?> Ok(Dictionary<string, object?> value) =>
        new() { ["ok"] = value };

    private static Dictionary<string, object?> Cancelled() =>
        new() { ["cancelled"] = new Dictionary<string, object?>() };

    internal static Dictionary<string, object?> Failed(string message) =>
        new() { ["failed"] = new Dictionary<string, object?> { ["message"] = message } };

    // ── Reading the payload ─────────────────────────────────────────────
    //
    // The payload is whatever the app sent. Anything that is not the expected
    // shape reads as absent, never as an exception: `files.open` with no
    // `accept` is "any file", and `files.save` with no `suggestedName` fails
    // the plain-name rule like an empty one.

    private static string? Text(JsonElement payload, string key)
    {
        if (payload.ValueKind != JsonValueKind.Object
            || !payload.TryGetProperty(key, out var value)
            || value.ValueKind != JsonValueKind.String)
        {
            return null;
        }
        try
        {
            return value.GetString();
        }
        catch (InvalidOperationException)
        {
            // JSON can escape a lone surrogate (`"\ud800"`), which is not a
            // string .NET will produce; it is not a file name either.
            return null;
        }
    }

    /// <summary>The extensions for the accepted MIME types, deduplicated, in order.</summary>
    private static List<string> ExtensionsFor(JsonElement payload)
    {
        var extensions = new List<string>();
        if (payload.ValueKind != JsonValueKind.Object
            || !payload.TryGetProperty("accept", out var accept)
            || accept.ValueKind != JsonValueKind.Array)
        {
            return extensions;
        }
        foreach (var entry in accept.EnumerateArray())
        {
            if (entry.ValueKind != JsonValueKind.String) continue;
            var mime = entry.GetString();
            foreach (var row in MimeExtensions)
            {
                if (row.Mime != mime) continue;
                foreach (var extension in row.Extensions)
                {
                    if (!extensions.Contains(extension)) extensions.Add(extension);
                }
            }
        }
        return extensions;
    }

    /// <summary>The text after the last <c>.</c> of a file name, or empty.</summary>
    private static string ExtensionOf(string name)
    {
        var dot = name.LastIndexOf('.');
        return dot < 0 ? string.Empty : name[(dot + 1)..];
    }

    private static string MimeTypeFor(string name)
    {
        var extension = ExtensionOf(name).ToLowerInvariant();
        foreach (var row in MimeExtensions)
        {
            if (Array.IndexOf(row.Extensions, extension) >= 0) return row.Mime;
        }
        return "application/octet-stream";
    }

    // ── The plain-name rule ─────────────────────────────────────────────

    /// <summary>
    /// A suggested name is a plain file name (UI87 §3.1), so an app cannot
    /// steer the picker, or disguise what it is saving -- the same rule as
    /// the Compose library:
    /// <list type="bullet">
    /// <item>no directory separators, and not <c>.</c> or <c>..</c> -- no other directory;</item>
    /// <item>no leading <c>.</c> -- a hidden dot-file such as <c>.zshrc</c> is
    /// configuration a shell or tool runs, not a document;</item>
    /// <item>no <c>:</c> -- on Windows <c>D:x</c> names another drive, and
    /// <c>x:y</c> an alternate data stream;</item>
    /// <item>no control, format, line- or paragraph-separator characters -- a
    /// right-to-left override can make <c>invoice&lt;RLO&gt;fdp.exe</c> read as a
    /// PDF in the picker, and a separator breaks the name across lines;</item>
    /// <item>no lone surrogate, unassigned or private-use code point -- they
    /// mean different things to different runtimes' Unicode tables;</item>
    /// <item>no leading or trailing whitespace of any kind (a no-break space
    /// included), no run of two or more, and no trailing dot, which Windows
    /// silently strips -- <c>report.pdf</c> padded out and ending
    /// <c>.command</c> hides its real extension. Blank-rendering characters
    /// (Hangul fillers, BRAILLE PATTERN BLANK) count as whitespace, and
    /// invisible (default-ignorable) characters are dropped before these
    /// padding and dot rules;</item>
    /// <item>at most 255 UTF-16 units.</item>
    /// </list>
    /// Checked by code point, so a format character outside the BMP (the tag
    /// characters, U+E0000..) is caught as well as one inside it.
    /// </summary>
    public static bool IsPlainFileName(string name)
    {
        if (name.Length == 0 || name.Length > 255 || name == "." || name == "..") return false;
        var points = CodePoints(name);
        if (points is null) return false;
        foreach (var point in points)
        {
            if (point == '/' || point == '\\' || point == ':') return false;
            switch (CharUnicodeInfo.GetUnicodeCategory(point))
            {
                case UnicodeCategory.Control:
                case UnicodeCategory.Format:
                case UnicodeCategory.LineSeparator:
                case UnicodeCategory.ParagraphSeparator:
                case UnicodeCategory.Surrogate:
                case UnicodeCategory.OtherNotAssigned:
                case UnicodeCategory.PrivateUse:
                    return false;
            }
        }
        // The padding and dot rules look at what is visible: invisible
        // characters cannot split a run of spaces or hide a leading or
        // trailing dot.
        var visible = points.FindAll(point => !IsInvisible(point));
        if (visible.Count == 0) return false;
        if (visible[0] == '.' || visible[^1] == '.') return false;
        if (IsSpace(visible[0]) || IsSpace(visible[^1])) return false;
        for (var index = 1; index < visible.Count; index += 1)
        {
            if (IsSpace(visible[index - 1]) && IsSpace(visible[index])) return false;
        }
        return true;
    }

    /// <summary>
    /// The code points of <paramref name="name"/>, or null when it holds a
    /// lone surrogate (which cannot be a file name). Walked by hand because
    /// <c>string.EnumerateRunes</c> would quietly replace one with U+FFFD.
    /// </summary>
    private static List<int>? CodePoints(string name)
    {
        var points = new List<int>(name.Length);
        for (var index = 0; index < name.Length; index += 1)
        {
            var unit = name[index];
            if (char.IsHighSurrogate(unit))
            {
                if (index + 1 >= name.Length || !char.IsLowSurrogate(name[index + 1])) return null;
                points.Add(char.ConvertToUtf32(unit, name[index + 1]));
                index += 1;
            }
            else if (char.IsLowSurrogate(unit))
            {
                return null;
            }
            else
            {
                points.Add(unit);
            }
        }
        return points;
    }

    /// <summary>
    /// Characters that are not whitespace to Unicode but render as a wide
    /// blank, so they pad a name just as well: the Hangul fillers and BRAILLE
    /// PATTERN BLANK. Whitespace for the padding rules.
    /// </summary>
    private static bool IsBlank(int point) =>
        point is 0x115F or 0x1160 or 0x2800 or 0x3164 or 0xFFA0;

    /// <summary>
    /// Whitespace as the Compose library means it: Java's
    /// <c>isWhitespace || isSpaceChar</c> -- every space, line and paragraph
    /// separator (no-break spaces included), the ASCII whitespace controls --
    /// plus the blanks above.
    /// </summary>
    private static bool IsSpace(int point)
    {
        if (point is >= 0x09 and <= 0x0D or >= 0x1C and <= 0x1F || IsBlank(point)) return true;
        return CharUnicodeInfo.GetUnicodeCategory(point) is UnicodeCategory.SpaceSeparator
            or UnicodeCategory.LineSeparator or UnicodeCategory.ParagraphSeparator;
    }

    /// <summary>
    /// Unicode's Default_Ignorable_Code_Point (.NET has no property for it),
    /// minus the blanks above: variation selectors, COMBINING GRAPHEME JOINER
    /// and the like -- the same ranges as the Compose library. Dropped before
    /// the padding and dot rules, so <c>&lt;space&gt;&lt;VS1&gt;&lt;space&gt;</c> is
    /// still a run while an emoji's own selector (<c>❤️ list.txt</c>) is fine.
    /// </summary>
    private static bool IsInvisible(int point) =>
        !IsBlank(point) && (
            point == 0x00AD || point == 0x034F || point == 0x061C
            || point is >= 0x115F and <= 0x1160 || point is >= 0x17B4 and <= 0x17B5
            || point is >= 0x180B and <= 0x180F || point is >= 0x200B and <= 0x200F
            || point is >= 0x202A and <= 0x202E || point is >= 0x2060 and <= 0x206F
            || point == 0x3164 || point is >= 0xFE00 and <= 0xFE0F || point == 0xFEFF
            || point == 0xFFA0 || point is >= 0xFFF0 and <= 0xFFF8
            || point is >= 0x1BCA0 and <= 0x1BCA3 || point is >= 0x1D173 and <= 0x1D17A
            || point is >= 0xE0000 and <= 0xE0FFF);

    /// <summary>True when <paramref name="name"/> ends in an extension from <see cref="ExecutableExtensions"/>.</summary>
    public static bool HasExecutableExtension(string name)
    {
        // Folded through upper case first: `ſ` (LONG S) lowercases to itself
        // but is `S` to a case-insensitive file system.
        return name.Contains('.')
            && ExecutableExtensions.Contains(ExtensionOf(name).ToUpperInvariant().ToLowerInvariant());
    }

    // ── files.open ──────────────────────────────────────────────────────

    /// <summary>What reading the chosen file came to.</summary>
    private enum ReadOutcome { Ok, NotRegular, TooLarge, Unreadable }

    /// <summary>
    /// Read at most <paramref name="limit"/> bytes. Bounded while reading, not
    /// by checking the length first: a file can grow between a check and a
    /// read, which is the TOCTOU the first XAML handler's review found (#15218).
    /// </summary>
    /// <remarks>
    /// The type is checked on the path (<c>File.Exists</c> is false for a
    /// directory) and again on the open stream: a disk file is seekable, and a
    /// pipe or device swapped in between is not. .NET has no <c>O_NONBLOCK</c>,
    /// so unlike the SwiftUI and Qt libraries this cannot refuse a Unix FIFO
    /// without first blocking on it; that matters nowhere this library runs --
    /// the WinUI picker only shows the Windows file system, which has none.
    /// </remarks>
    private static ReadOutcome ReadChosenFile(string path, long limit, out byte[] bytes)
    {
        bytes = Array.Empty<byte>();
        if (!File.Exists(path)) return ReadOutcome.NotRegular;
        try
        {
            using var stream = new FileStream(path, new FileStreamOptions
            {
                Mode = FileMode.Open,
                Access = FileAccess.Read,
                // Another program may keep the file open for writing (a
                // photo library, an editor); the bound below is what makes
                // that safe to allow.
                Share = FileShare.ReadWrite | FileShare.Delete,
                Options = FileOptions.SequentialScan,
            });
            if (!stream.CanSeek) return ReadOutcome.NotRegular;
            using var output = new MemoryStream();
            var buffer = new byte[64 * 1024];
            while (true)
            {
                var got = stream.Read(buffer, 0, buffer.Length);
                if (got <= 0) break;
                if (output.Length + got > limit) return ReadOutcome.TooLarge;
                output.Write(buffer, 0, got);
            }
            bytes = output.ToArray();
            return ReadOutcome.Ok;
        }
        catch (Exception)
        {
            return ReadOutcome.Unreadable;
        }
    }

    /// <summary><c>files.open</c>: the outcome, never an exception from the file.</summary>
    public static async Task<Dictionary<string, object?>> RunFilesOpenAsync(
        JsonElement payload, IMosaicFileDialogs dialogs)
    {
        var chosen = await dialogs.ChooseFileToOpenAsync(ExtensionsFor(payload));
        if (chosen is null) return Cancelled();
        // Not the exception's own text: it can carry the full local path, and
        // a failure message is data the app sees.
        switch (ReadChosenFile(chosen, MaxOpenBytes, out var bytes))
        {
            case ReadOutcome.NotRegular:
                return Failed("that is not a regular file");
            case ReadOutcome.TooLarge:
                return Failed(string.Create(
                    CultureInfo.InvariantCulture, $"the selected file is larger than {MaxOpenBytes} bytes"));
            case ReadOutcome.Unreadable:
                return Failed("couldn't read the selected file");
        }
        var name = Path.GetFileName(chosen);
        return Ok(new Dictionary<string, object?>
        {
            ["name"] = name,
            ["mimeType"] = MimeTypeFor(name),
            ["bytes"] = Convert.ToBase64String(bytes),
        });
    }

    // ── files.save ──────────────────────────────────────────────────────

    /// <summary>True when every character is in the base64 alphabet or is padding.</summary>
    /// <remarks>
    /// Checked before decoding because <c>Convert.FromBase64String</c> skips
    /// whitespace, where the Compose and SwiftUI decoders refuse it; the same
    /// payload should not save on one host and fail on another.
    /// </remarks>
    private static bool IsBase64Alphabet(string encoded)
    {
        foreach (var character in encoded)
        {
            if (character is not ((>= 'A' and <= 'Z') or (>= 'a' and <= 'z') or (>= '0' and <= '9')
                or '+' or '/' or '='))
            {
                return false;
            }
        }
        return true;
    }

    /// <summary><c>files.save</c>: the outcome, never an exception from the file.</summary>
    public static async Task<Dictionary<string, object?>> RunFilesSaveAsync(
        JsonElement payload, IMosaicFileDialogs dialogs)
    {
        var suggestedName = Text(payload, "suggestedName") ?? string.Empty;
        if (!IsPlainFileName(suggestedName))
        {
            return Failed("suggestedName must be a plain file name");
        }
        if (Text(payload, "bytes") is not { } encoded)
        {
            return Failed("bytes must be base64 text");
        }
        // Checked on the encoded length before decoding, so an oversized
        // payload is refused without allocating its decoded copy (4 base64
        // chars = 3 bytes).
        if ((long)encoded.Length > ((long)MaxSaveBytes / 3 + 1) * 4)
        {
            return Failed(string.Create(
                CultureInfo.InvariantCulture, $"the file is larger than {MaxSaveBytes} bytes"));
        }
        byte[] bytes;
        try
        {
            if (!IsBase64Alphabet(encoded)) return Failed("bytes must be base64 text");
            bytes = Convert.FromBase64String(encoded);
        }
        catch (FormatException)
        {
            return Failed("bytes must be base64 text");
        }
        if (bytes.Length > MaxSaveBytes)
        {
            return Failed(string.Create(
                CultureInfo.InvariantCulture, $"the file is larger than {MaxSaveBytes} bytes"));
        }
        // When the app says what it is saving, the name must agree: a JSON
        // export cannot be offered as `notes.exe`. Compared as Compose
        // compares it (lower case, no upper-case fold): the fold is for
        // catching launchers, not for widening what matches a type.
        var extensions = ExtensionsFor(payload);
        var lowered = suggestedName.ToLowerInvariant();
        if (extensions.Count > 0
            && !extensions.Exists(extension => lowered.EndsWith("." + extension, StringComparison.Ordinal)))
        {
            return Failed("suggestedName must end in an extension of an accepted type");
        }
        if (extensions.Count == 0 && HasExecutableExtension(suggestedName))
        {
            return Failed("suggestedName must not end in an executable extension");
        }
        var target = await dialogs.ChooseFileToSaveAsync(suggestedName, extensions);
        if (target is null) return Cancelled();
        return WriteReplacing(target, bytes);
    }

    /// <summary>
    /// Write <paramref name="bytes"/> beside <paramref name="target"/> and move
    /// it into place, so an interrupted save never leaves a half-written file
    /// where the person's old one was.
    /// </summary>
    /// <remarks>
    /// <list type="bullet">
    /// <item>The temporary file is created exclusively (<c>FileMode.CreateNew</c>,
    /// <c>O_CREAT|O_EXCL</c> on Unix, which also refuses a planted symlink) and,
    /// on Unix, owner-only (0600).</item>
    /// <item>On Unix it takes the rwx bits of the file it replaces -- never
    /// setuid, setgid or sticky -- through the open handle, as <c>fchmod</c>
    /// would, so saving over a private file never leaves the new one readable
    /// by other users. On Windows the file's ACL is inherited from the folder,
    /// as the Compose and Qt libraries leave it.</item>
    /// <item>It is flushed to disk, then moved over the target with
    /// <c>File.Move(overwrite: true)</c>: <c>rename(2)</c> on Unix and
    /// <c>MoveFileEx(MOVEFILE_REPLACE_EXISTING)</c> on Windows, both a single
    /// step within one folder. <c>File.Replace</c> was not used: it fails when
    /// the target does not exist yet, which is the common case for a save.</item>
    /// </list>
    /// </remarks>
    private static Dictionary<string, object?> WriteReplacing(string target, byte[] bytes)
    {
        string? temporary = null;
        try
        {
            var full = Path.GetFullPath(target);
            var directory = Path.GetDirectoryName(full);
            if (string.IsNullOrEmpty(directory)) return Failed("couldn't save the file");
            temporary = Path.Combine(directory, ".mosaic-save-" + Guid.NewGuid().ToString("N") + ".tmp");
            var options = new FileStreamOptions
            {
                Mode = FileMode.CreateNew,
                Access = FileAccess.Write,
                Share = FileShare.None,
            };
            if (!OperatingSystem.IsWindows())
            {
                options.UnixCreateMode = UnixFileMode.UserRead | UnixFileMode.UserWrite;
            }
            using (var stream = new FileStream(temporary, options))
            {
                stream.Write(bytes, 0, bytes.Length);
                if (!OperatingSystem.IsWindows()) CopyPermissions(full, stream);
                stream.Flush(flushToDisk: true);
            }
            File.Move(temporary, full, overwrite: true);
            temporary = null;
            return Ok(new Dictionary<string, object?> { ["name"] = Path.GetFileName(full) });
        }
        catch (Exception)
        {
            return Failed("couldn't save the file");
        }
        finally
        {
            if (temporary is not null)
            {
                try { File.Delete(temporary); } catch (Exception) { /* best effort */ }
            }
        }
    }

    /// <summary>
    /// Give the temporary file the rwx bits of the regular file it replaces,
    /// when there is one. A symlink or a new name keeps the owner-only default.
    /// </summary>
    [UnsupportedOSPlatform("windows")]
    private static void CopyPermissions(string target, FileStream temporary)
    {
        var existing = new FileInfo(target);
        if (!existing.Exists || existing.LinkTarget is not null) return;
        const UnixFileMode rwx = (UnixFileMode)0x1FF; // user, group, other: rwx
        File.SetUnixFileMode(temporary.SafeFileHandle, existing.UnixFileMode & rwx);
    }

    // ── Routing and installation ────────────────────────────────────────

    /// <summary>
    /// Route one effect (UI87 §7.2). True when this library takes it, false
    /// when it belongs to the app's handler, and null when nobody should
    /// answer it here (the host then fails an unanswered Await).
    /// </summary>
    public static bool? RoutesToPlatform(string kind, IReadOnlySet<string>? appKinds)
    {
        if (appKinds is not null && appKinds.Contains(kind)) return false;
        if (StandardEffectKinds.Contains(kind)) return true;
        if (appKinds is null) return false;
        return null;
    }

    /// <summary>
    /// Install the platform library on <paramref name="host"/>, wrapping
    /// whatever handler the app installed. <paramref name="appKinds"/> is the
    /// app's <c>[host_effects]</c> <c>kinds</c>, or null when it declared none
    /// (the original meaning: it receives every non-standard kind).
    /// <paramref name="runOnUi"/> queues work on the UI thread and says whether
    /// it was queued. <paramref name="dialogs"/> and <paramref name="runOnUi"/>
    /// are replaceable for tests.
    /// </summary>
    /// <remarks>
    /// Idempotent: when the host's handler is already a router, the app did
    /// not reinstall its own since, and nothing changes. A retried startup
    /// (<c>Close</c>, then <c>LoadRequired</c>) is a new runtime with no
    /// handler, so it gets a new router, as it gets the app's handler again.
    /// </remarks>
    public static void Install(
        IMosaicPlatformEffectHost host,
        IEnumerable<string>? appKinds,
        IMosaicFileDialogs dialogs,
        Func<Action, bool> runOnUi)
    {
        var current = host.EffectHandler;
        if (current?.Target is MosaicPlatformRouter) return;
        var claimed = appKinds is null ? null : new HashSet<string>(appKinds, StringComparer.Ordinal);
        var router = new MosaicPlatformRouter(host, current, claimed, dialogs, runOnUi);
        host.EffectHandler = router.Handle;
    }

#if !MOSAIC_HEADLESS_TEST
    /// <summary>
    /// Install the platform library for <paramref name="window"/>: its handle
    /// owns the pickers and its DispatcherQueue runs them. Called by the
    /// generated MainWindow after <c>MosaicRuntimeHost.LoadRequired()</c> and
    /// the package's own handler -- before <c>LoadRequired</c>, the host's
    /// <c>EffectHandler</c> setter assigns nothing.
    /// </summary>
    public static void Install(global::Microsoft.UI.Xaml.Window window, IEnumerable<string>? appKinds)
    {
        // An unpackaged WinUI 3 app has no CoreWindow, so a picker must be
        // told which window owns it (InitializeWithWindow) or it throws.
        var handle = global::WinRT.Interop.WindowNative.GetWindowHandle(window);
        var queue = window.DispatcherQueue;
        Install(
            MosaicRuntimeHostEffects.Instance,
            appKinds,
            new WinUIMosaicFileDialogs(handle),
            work => queue.TryEnqueue(() => work()));
    }
#endif
}

/// <summary>
/// The handler this library installs: it routes each effect by kind (UI87
/// §7.2) and answers the standard kinds itself. A named class, so installing
/// twice is recognisable -- a second router would wrap the first.
/// </summary>
public sealed class MosaicPlatformRouter
{
    private readonly IMosaicPlatformEffectHost host;
    private readonly Action<ulong, string, JsonElement, string>? appHandler;
    private readonly IReadOnlySet<string>? appKinds;
    private readonly IMosaicFileDialogs dialogs;
    private readonly Func<Action, bool> runOnUi;

    // One file operation at a time (UI87 §3.1): a second request while a
    // picker is open is failed, not queued behind it. 0 = free, 1 = busy;
    // an int for Interlocked, since the handler may run on whichever thread
    // settled the effect.
    private int busy;

    internal MosaicPlatformRouter(
        IMosaicPlatformEffectHost host,
        Action<ulong, string, JsonElement, string>? appHandler,
        IReadOnlySet<string>? appKinds,
        IMosaicFileDialogs dialogs,
        Func<Action, bool> runOnUi)
    {
        this.host = host;
        this.appHandler = appHandler;
        this.appKinds = appKinds;
        this.dialogs = dialogs;
        this.runOnUi = runOnUi;
    }

    public void Handle(ulong id, string kind, JsonElement payload, string delivery)
    {
        switch (MosaicPlatformEffects.RoutesToPlatform(kind, appKinds))
        {
            case false:
                // The app's, delivered as it was before the router existed. An
                // exception from it reaches the host's own catch, which fails
                // the effect with the reason -- exactly as it did then.
                appHandler?.Invoke(id, kind, payload, delivery);
                return;
            case null:
                return; // nobody: the host fails an unanswered Await
            case true:
                AnswerStandard(id, kind, payload, delivery);
                return;
        }
    }

    private void AnswerStandard(ulong id, string kind, JsonElement payload, string delivery)
    {
        // Only an Await has someone waiting for the answer.
        if (!string.Equals(delivery, "await", StringComparison.OrdinalIgnoreCase)) return;
        if (Interlocked.CompareExchange(ref busy, 1, 0) != 0)
        {
            // Inline: the host's lock is reentrant, and this is its settle.
            host.CompleteEffect(id, MosaicPlatformEffects.Failed("another file operation is in progress"));
            return;
        }
        // The payload belongs to the host's parsed update, which is not
        // guaranteed to outlive this call; the picker answers long after it.
        // A missing payload (Undefined) has nothing to copy.
        var request = payload.ValueKind == JsonValueKind.Undefined ? payload : payload.Clone();
        // Ownership first. False means the runtime is not waiting on this id,
        // and the right move is to open no picker at all.
        if (!host.DeferEffect(id))
        {
            Volatile.Write(ref busy, 0);
            return;
        }
        bool queued;
        try
        {
            // AnswerAsync catches everything it can meet, so the discarded
            // task never faults.
            queued = runOnUi(() => _ = AnswerAsync(id, kind, request));
        }
        catch (Exception)
        {
            queued = false;
        }
        if (!queued)
        {
            // The window is closing and its queue refused the work. Deferred,
            // so the host will not fail it: this is the last chance to answer.
            Volatile.Write(ref busy, 0);
            TryComplete(id, MosaicPlatformEffects.Failed("the file dialog failed"));
        }
    }

    private async Task AnswerAsync(ulong id, string kind, JsonElement request)
    {
        Dictionary<string, object?> outcome;
        try
        {
            outcome = kind == "files.open"
                ? await MosaicPlatformEffects.RunFilesOpenAsync(request, dialogs)
                : await MosaicPlatformEffects.RunFilesSaveAsync(request, dialogs);
        }
        catch (Exception)
        {
            // A picker that threw (no window, an elevated process, a file
            // with no local path) -- not its text, which can carry a path.
            outcome = MosaicPlatformEffects.Failed("the file dialog failed");
        }
        finally
        {
            Volatile.Write(ref busy, 0);
        }
        TryComplete(id, outcome);
    }

    private void TryComplete(ulong id, object outcome)
    {
        try
        {
            host.CompleteEffect(id, outcome);
        }
        catch (Exception)
        {
            // The runtime was closed while the picker was open (a failed
            // start's Close, or process exit). Nothing is waiting any more.
        }
    }
}

#if !MOSAIC_HEADLESS_TEST
/// <summary>
/// WinUI 3's own pickers, owned by the app's window. Returns full paths: the
/// library reads and writes through System.IO so the bounded read and the
/// temporary-then-move save are the same code the headless test runs.
/// </summary>
public sealed class WinUIMosaicFileDialogs : IMosaicFileDialogs
{
    private readonly IntPtr window;

    public WinUIMosaicFileDialogs(IntPtr window) => this.window = window;

    public async Task<string?> ChooseFileToOpenAsync(IReadOnlyList<string> extensions)
    {
        var picker = new global::Windows.Storage.Pickers.FileOpenPicker
        {
            ViewMode = global::Windows.Storage.Pickers.PickerViewMode.List,
            SuggestedStartLocation = global::Windows.Storage.Pickers.PickerLocationId.DocumentsLibrary,
        };
        // FileTypeFilter must hold at least one entry or the picker throws;
        // `*` is "any file", which is what no accepted type means (UI59 §3).
        if (extensions.Count == 0)
        {
            picker.FileTypeFilter.Add("*");
        }
        else
        {
            foreach (var extension in extensions) picker.FileTypeFilter.Add("." + extension);
        }
        global::WinRT.Interop.InitializeWithWindow.Initialize(picker, window);
        return PathOf(await picker.PickSingleFileAsync());
    }

    public async Task<string?> ChooseFileToSaveAsync(string suggestedName, IReadOnlyList<string> extensions)
    {
        // The picker adds the chosen type's extension to the name it shows,
        // so it is given the name without one, and the suggested name's own
        // extension comes first among the choices. When the app named types,
        // the name already ends in one of them (checked before this runs).
        var dot = suggestedName.LastIndexOf('.');
        var own = dot > 0 ? suggestedName[dot..] : string.Empty;
        var choices = new List<string>();
        if (own.Length > 1) choices.Add(own);
        foreach (var extension in extensions)
        {
            var dotted = "." + extension;
            if (!choices.Exists(choice => string.Equals(choice, dotted, StringComparison.OrdinalIgnoreCase)))
            {
                choices.Add(dotted);
            }
        }
        // A name with no extension: FileTypeChoices must not be empty, and
        // "." is the entry that lets the picker keep a name without one.
        if (choices.Count == 0) choices.Add(".");
        var picker = new global::Windows.Storage.Pickers.FileSavePicker
        {
            SuggestedStartLocation = global::Windows.Storage.Pickers.PickerLocationId.DocumentsLibrary,
            SuggestedFileName = own.Length > 1 ? suggestedName[..dot] : suggestedName,
        };
        picker.FileTypeChoices.Add("Files", choices);
        global::WinRT.Interop.InitializeWithWindow.Initialize(picker, window);
        return PathOf(await picker.PickSaveFileAsync());
    }

    /// <summary>
    /// The chosen file's path, or null when the person cancelled. A file with
    /// no local path (a provider that serves only a stream) cannot be read or
    /// written through System.IO, so it throws -- failed, not a cancel nobody
    /// made.
    /// </summary>
    private static string? PathOf(global::Windows.Storage.StorageFile? file)
    {
        if (file is null) return null;
        if (string.IsNullOrEmpty(file.Path))
        {
            throw new InvalidOperationException("the chosen file has no local path");
        }
        return file.Path;
    }
}
#endif
